            if (renderRequest.AsyncOption.IsSet)
                writer.WriteBoolean("async", renderRequest.AsyncOption.Value!.Value);

            if (renderRequest.SigningOption.IsSet)
            {
                writer.WritePropertyName("signing");
                JsonSerializer.Serialize(writer, renderRequest.Signing, jsonSerializerOptions);
            }
            if (renderRequest.SubjectOption.IsSet)
                writer.WriteString("subject", renderRequest.Subject);
        }
    }
}
